import json
from itertools import permutations

def solve_puzzle():
    # Input variables
    houses = [1, 2, 3]  # left (1) to right (3)
    names = ["Eric", "Arnold", "Peter"]
    book_genres = ["mystery", "science fiction", "romance"]
    vacations = ["mountain", "beach", "city"]

    solutions = []

    # Iterate over all possible assignments
    for name_at_houses in permutations(names):
        pos_name = {name: i + 1 for i, name in enumerate(name_at_houses)}

        # Clue 1: Eric is directly left of Arnold.
        if not (pos_name["Eric"] + 1 == pos_name["Arnold"]):
            continue

        for genre_at_houses in permutations(book_genres):
            pos_genre = {genre: i + 1 for i, genre in enumerate(genre_at_houses)}

            # Clue 4: The person who loves mystery books is somewhere to the left of the person who loves beach vacations.
            # Clue 5 (used partially here to allow pruning): science fiction books is the person who loves beach vacations.
            # We cannot check clue 4/5 fully yet without vacation positions, but we can do partial checks later.

            for vac_at_houses in permutations(vacations):
                pos_vac = {vac: i + 1 for i, vac in enumerate(vac_at_houses)}

                # Apply remaining clues:
                # Clue 5: The person who loves science fiction books is the person who loves beach vacations.
                if not (pos_genre["science fiction"] == pos_vac["beach"]):
                    continue

                # Clue 4: The person who loves mystery books is somewhere to the left of the person who loves beach vacations.
                if not (pos_genre["mystery"] < pos_vac["beach"]):
                    continue

                # Clue 3: Peter is the person who prefers city breaks.
                if not (pos_name["Peter"] == pos_vac["city"]):
                    continue

                # Clue 2: Peter is somewhere to the right of the person who loves beach vacations.
                if not (pos_name["Peter"] > pos_vac["beach"]):
                    continue

                # All constraints satisfied; record solution
                solution = {
                    "name_at_houses": list(name_at_houses),
                    "genre_at_houses": list(genre_at_houses),
                    "vac_at_houses": list(vac_at_houses),
                }
                solutions.append(solution)

    if not solutions:
        raise ValueError("No solution found for the given puzzle.")

    # Expect a unique solution; take the first
    sol = solutions[0]

    header = ["House", "Name", "favorite book genres", "type of vacation"]
    rows = []
    for i in range(3):
        house_num = str(i + 1)
        name = sol["name_at_houses"][i]
        genre = sol["genre_at_houses"][i]
        vac = sol["vac_at_houses"][i]
        rows.append([house_num, name, genre, vac])

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False, indent=2))
